body {
    margin: 0 0 0 0;
    font-size: 14px;
    font-family: "Segoe UI","Helvetica Neue", Helvetica, Arial, sans-serif;
}

a {
    color: #003399;
    font-size: inherit;
    text-decoration: none;
}

a:hover {
    color: #000000;
    text-decoration: underline;
}

p {
    padding: 0px;
    margin: 0px;
}

/* Override default borders for images nested within 'a' tags */
a img {
    border: none;
}

.msrs-label {
    font-size: x-small;
}

.msrs-normal {
    color: Black;
    font-size: inherit;
    font-weight: normal;
    font-family: inherit;
}

.msrs-parameterLabel {
    font-size: x-small;
    font-weight: bold;
}

.msrs-normalwithmargin {
    color: Black;
    font-size: x-small;
    font-weight: normal;
    margin-left: 20px;
}

/* Title Text of a section header */
.msrs-sectionheader {
    color: black;
    font-size: small;
    font-weight: bold;
    padding-top: 10px;
}

/* Title text of a section header on the Report Properties page */
.msrs-rptSectionHead {
    color: black;
    font-size: x-small;
    font-weight: bold;
}

/* Links on page */
.msrs-nav {
    text-decoration: none;
    font-size: x-small;
    font-weight: normal;
    color: #3366CC;
}

/* Lower title on the page */
.msrs-lowertitle {
    font-size: 16px;
    font-weight: bold;
}

/* drop downs */
.msrs-dropdowns {
    font-size: inherit;
    font-family: inherit;
}

/* Upper title on the page */
.msrs-uppertitle {
    font-size: x-small;
}

/* Breadcrumb links */
.msrs-linkpanel {
    color: Black;
    font-size: x-small;
}

    .msrs-linkpanel a {
        font-size: x-small;
        font-weight: normal;
        color: Black;
    }

/* Item in a list */
.msrs-listItem {
    color: Black;
    font-size: x-small;
    padding-left: 2px;
    padding-right: 8px;
}

/* Item in a list */
.msrs-iconListItem {
    color: Black;
    font-size: x-small;
    padding-left: 10px;
    padding-right: 8px;
    padding-top: 4px;
}

.msrs-listItem a {
    color: #000000;
    font-size: x-small;
}

/* Global links at top of page */
.msrs-banner {
    color: #3366CC;
    background-color: #FDFDFE;
    font-size: 10px;
    font-weight: normal;
    padding: 2px;
}

.msrs-bannerframe {
    background-color: #3366CC;
}

/* Sub tabs */
.msrs-subtab {
    color: #CCCCCC;
    background-color: #ece9d8;
    font-size: xx-small;
    font-weight: bold;
    padding: 2px;
}

.msrs-subtabAsian {
    color: #CCCCCC;
    background-color: #ece9d8;
    font-size: x-small;
    font-weight: bold;
    padding: 2px;
}

.msrs-subtab a {
    font-size: xx-small;
}

.msrs-subtabAsian a {
    font-size: x-small;
}

/* Label of search box*/
.msrs-search {
    font-size: x-small;
    color: black;
    font-weight: normal;
    text-decoration: none;
}

/* Area containing page titles */
.msrs-titleareaframe {
    color: black;
    border-right: none;
}

/* Invalid data entered by user on page. */
.msrs-validationerror {
    font-size: inherit;
    color: Red;
    font-weight: normal;
    text-decoration: none;
}

/* Valid data entered by user on page. */
.msrs-valid {
    font-size: x-small;
    color: green;
    font-weight: normal;
    text-decoration: none;
}

/* Header of a sortable column in a table list */
.msrs-listHeader {
    text-align: left;
    font-weight: normal;
    color: #999999;
    padding-left: 2px;
}

.msrs-listHeaderPadded {
    color: #3366CC;
    font-size: x-small;
    text-align: left;
    cursor: pointer;
    border: 1px solid white;
    padding-left: 0px;
    padding-right: 8px;
}

/* Header of a non-sortable column in a table list */
.msrs-nosortListHeader {
    background-color: #eaeef6;
    font-size: x-small;
    text-align: left;
    padding-left: 1px;
    padding-right: 8px;
    font-weight: normal;
}

.msrs-thinPageBorder {
    background-color: #FFCC00;
    width: 100%;
}

/* Tab control */
.msrs-tabs {
    background-color: white;
}

.msrs-tabSeparator {
    border-bottom: 5px solid #3366CC;
}

/*
 * Shared area
 * /

/* Content frame, including left & right borders, tab strip, and content */
.msrs-contentFrame {
    background-color: White;
    width: 100%;
    height: 100%;
}

.msrs-innerContentFrame {
    background-color: White;
    border-top: 4px solid #FFCC00;
    width: 100%;
    height: 100%;
}

.msrs-CalendarTitle {
    background: #336699;
    color: White;
}

.msrs-CalendarDayHeaderStyle {
    background: #ffcc00;
    font-size: x-small;
}

.msrs-CalendarWeekendDayStyle {
    background: #ffffff;
}

.msrs-CalendarSelectedDayStyle {
    background: red;
}

/* buttons for performing actions on multiple items in a checkbox list */
.msrs-buttonHeaderButton {
    margin: 1px 1px 1px 1px;
    cursor: pointer;
}

.msrs-buttonHeaderText {
    font-size: x-small;
    font-family: "Segoe UI","Helvetica Neue", Helvetica, Arial, sans-serif;
    color: Black;
}

.msrs-buttonHeaderButtonHover {
    border: 1px solid #6a7c8e;
    background-color: #FFFFFF;
    cursor: pointer;
}

.msrs-buttonHeaderButtonHoverPressed {
    border: 1px solid #6a7c8e;
    background-color: #99ccff;
    cursor: pointer;
}

.msrs-buttonHeaderSeparator {
    color: #3366CC;
}

.msrs-buttonHeaderBackground {
    background-color: #ece9d8;
}

/* Generic buttons */
.msrs-button {
    font-size: x-small;
}

/* Link buttons */
.msrs-linkButton {
    color: #3366CC;
}

/* Generic text area */
.msrs-txtBox {
    font-size: inherit;
    font-family: inherit;
}

.msrs-normalCellWithSpaceForRadioButton {
    height: 30px;
    vertical-align: middle;
    color: Black;
    font-size: x-small;
    font-weight: normal;
}

/* Last Run text on folder list view */
.msrs-lastRunCell {
    font-size: x-small;
    font-style: italic;
}

.msrs-newPunc {
    font-size: x-small;
    font-weight: bold;
    color: Green;
}

.msrs-newText {
    font-size: xx-small;
    color: Green;
}

.msrs-newTextAsian {
    font-size: x-small;
    color: Green;
}

/* Spacer */
.msrs-space {
    margin: 0;
    padding: 0;
}

/* Unselected tab */
.msrs-unselectedTab {
    text-align: center;
    font-weight: bold;
